 7: const FALLBACK = {
 8:   0:   'تعذّر الاتصال بالخادم، تأكد من الإنترنت وحاول تاني',
 9:   403: 'ليس لديك صلاحية لتنفيذ هذا الإجراء',
10:   404: 'القسم غير موجود أو تم حذفه',
11:   409: 'البيانات اتغيرت من مستخدم تاني، حدّث الصفحة',
12:   422: 'البيانات غير صالحة',
13:   429: 'محاولات كتير، استنى شوية وحاول تاني',
14:   500: 'حصل خطأ في الخادم',
15: };
