 4: // API → شكل الـ UI (نفس أسماء الـ mock عشان الكومبوننتس متتغيرش)
 5: export function toUiNode(c, rootIndex = 0) {
 6:   return {
 7:     id: c.id,
 8:     parentId: c.parent_id,
 9:     ar: c.name_ar ?? '',
10:     en: c.name_en ?? '',
11:     slug: c.slug,
12:     desc_ar: c.description_ar ?? '',
13:     desc_en: c.description_en ?? '',
14:     order: c.sort_order ?? 0,
15:     status: c.is_active ? 'active' : 'inactive',
16:     products: c.products_count ?? 0,
17:     imageUrl: c.image_url,
18:     // الـ mock بيستخدم img كـ CSS background → نحافظ على نفس الشكل
19:     img: c.image_url
20:       ? `url("${c.image_url}") center / cover no-repeat`
21:       : (c.parent_id === null ? IMG[rootIndex % IMG.length] : undefined),
22:     createdAt: c.created_at,
23:     children: (c.children ?? []).map((ch) => toUiNode(ch)),
24:   };
25: }
26: 
27: export const toUiTree = (list) => list.map((c, i) => toUiNode(c, i));
28: 
29: // UI form → payload للـ API
30: export function toPayload(v, { isEdit } = {}) {
31:   const p = {
32:     name_ar: v.ar.trim(),
33:     name_en: v.en.trim(),
34:     parent_id: v.parentId ?? null,
35:     slug: v.slug?.trim() ? v.slug.trim().toLowerCase() : null, // فاضي → الباك يولّده
36:     description_ar: v.desc_ar?.trim() || null,
37:     description_en: v.desc_en?.trim() || null,
38:     sort_order: Number(toLatinDigits(v.order ?? 0)) || 0,
39:     is_active: v.status === 'active',
40:   };
41:   if (v.imageFile) p.image = v.imageFile;
42:   if (isEdit && v.imageRemoved && !v.imageFile) p.remove_image = true;
43:   return p;
44: }
