167: /* Table */
168: .v-table { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 13px; }
169: .v-table th { font-size: 11.5px; font-weight: 600; color: var(--text-muted); text-align: start; padding: 12px 14px; white-space: nowrap; border-bottom: 1px solid var(--divider-color); }
170: .v-table td { padding: 12px 14px; border-bottom: 1px solid var(--divider-color); vertical-align: middle; }
171: .v-table tbody tr { transition: background .12s; }
172: .v-table tbody tr:hover td { background: var(--bg-subcard); }
173: .v-table tbody tr:last-child td { border-bottom: 0; }
174: 
175: /* Skeleton */
176: @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
177: .skel { border-radius: 8px; background: linear-gradient(90deg, var(--bg-subcard) 0%, var(--bg-subcard-hover) 50%, var(--bg-subcard) 100%); background-size: 200% 100%; animation: shimmer 1.4s infinite linear; }
178: 
179: /* Motion */
180: @keyframes blurFadeIn { 0% { opacity: 0; filter: blur(10px); transform: translateY(8px); } 100% { opacity: 1; filter: blur(0); transform: none; } }
181: .stagger { animation: blurFadeIn .48s cubic-bezier(.22,1,.36,1) both; }
182: .s1 { animation-delay: .03s; } .s2 { animation-delay: .09s; } .s3 { animation-delay: .15s; } .s4 { animation-delay: .21s; } .s5 { animation-delay: .27s; }
183: @keyframes popIn { from { opacity: 0; transform: translateY(6px) scale(.98); } to { opacity: 1; transform: none; } }
184: .pop { animation: popIn .22s cubic-bezier(.22,1,.36,1) both; }
185: @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
186: .fade { animation: fadeIn .2s ease both; }
187: @keyframes spin { to { transform: rotate(360deg); } }
188: .spin { animation: spin .8s linear infinite; }
189: @keyframes stripe { to { background-position: 20px 0; } }
190: .progress-live { background: repeating-linear-gradient(-45deg, var(--accent) 0, var(--accent) 5px, var(--accent-2) 5px, var(--accent-2) 10px); background-size: 20px 100%; animation: stripe .6s linear infinite; }
191: 
192: @keyframes drawerIn { from { transform: translateX(-100%); } to { transform: none; } }
193: .drawer { animation: drawerIn .32s cubic-bezier(.22,1,.36,1) both; }
