123: function useOutside(ref, cb, active) {
124:   useEffect(() => {
125:     if (!active) return;
126:     const h = (e) => { if (ref.current && !e.composedPath().includes(ref.current)) cb(); };
127:     document.addEventListener('mousedown', h);
128:     return () => document.removeEventListener('mousedown', h);
129:   }, [active]);
130: }
