132: function SearchSelect({ value, onChange, options = [], placeholder = 'اختر…', error, disabled, loading: forceLoading, emptyText, multi, clearable = true, renderOption, asyncSim = true, searchPlaceholder = 'ابحث…' }) {
133:   const [open, setOpen] = useState(false);
134:   const [q, setQ] = useState('');
135:   const [loading, setLoading] = useState(false);
136:   const [hi, setHi] = useState(0);
137:   const ref = useRef(null);
138:   useOutside(ref, () => setOpen(false), open);
139:   useEffect(() => {
140:     if (!open || !asyncSim) return;
141:     setLoading(true);
142:     const t = setTimeout(() => setLoading(false), q ? 420 : 300);
143:     return () => clearTimeout(t);
144:   }, [q, open]);
145:   const isLoading = forceLoading || loading;
146:   const list = options.filter((o) => !q || (o.label + ' ' + (o.sub || '')).toLowerCase().includes(q.toLowerCase()));
147:   const selected = multi ? options.filter((o) => (value || []).includes(o.value)) : options.find((o) => o.value === value);
148:   const pick = (o) => {
149:     if (multi) {
150:       const cur = value || [];
151:       onChange(cur.includes(o.value) ? cur.filter((v) => v !== o.value) : [...cur, o.value]);
152:     } else { onChange(o.value); setOpen(false); setQ(''); }
153:   };
154:   const onKey = (e) => {
155:     if (e.key === 'ArrowDown') { e.preventDefault(); setHi((h) => Math.min(h + 1, list.length - 1)); }
156:     if (e.key === 'ArrowUp') { e.preventDefault(); setHi((h) => Math.max(h - 1, 0)); }
157:     if (e.key === 'Enter' && list[hi] && !list[hi].disabled) { e.preventDefault(); pick(list[hi]); }
158:     if (e.key === 'Escape') setOpen(false);
159:   };
160:   return (
161:     <div className="relative" ref={ref}>
162:       <button type="button" disabled={disabled} onClick={() => setOpen(!open)}
163:         className={cx('v-input flex items-center justify-between gap-2 text-start', open && 'is-focus', error && 'is-error', disabled && 'is-disabled', multi && selected.length && '!h-auto min-h-[42px] py-1.5')}>
164:         <span className="flex-1 min-w-0 flex items-center gap-1.5 flex-wrap">
165:           {multi ? (selected.length ? selected.map((s) => (
166:             <span key={s.value} className="inline-flex items-center gap-1 ps-2.5 pe-1 h-7 rounded-full text-[12px] font-medium" style={{ background: 'var(--bg-card)', border: '1px solid var(--border-field)' }}>
167:               {s.label}
168:               <span role="button" onClick={(e) => { e.stopPropagation(); pick(s); }} className="w-5 h-5 rounded-full inline-flex items-center justify-center hover:bg-[var(--bg-subcard-hover)] t-3"><Icon name="x" size={11} /></span>
169:             </span>
170:           )) : <span className="t-3">{placeholder}</span>)
171:             : selected ? <span className="truncate flex items-center gap-2">{selected.icon}{selected.label}{selected.sub && <span className="t-3 text-[11.5px]">· {selected.sub}</span>}</span>
172:             : <span className="t-3">{placeholder}</span>}
173:         </span>
174:         {!multi && clearable && selected && !disabled && (
175:           <span role="button" onClick={(e) => { e.stopPropagation(); onChange(null); }} className="w-6 h-6 rounded-full inline-flex items-center justify-center t-3 hover:bg-[var(--bg-subcard-hover)]"><Icon name="x" size={12} /></span>
176:         )}
177:         <Icon name="chevDown" size={14} className={cx('t-3 transition-transform', open && 'rotate-180')} />
178:       </button>
179:       {open && (
180:         <div className="pop absolute z-40 mt-2 w-full min-w-[260px] v-card p-2" style={{ boxShadow: 'var(--shadow-pop)', borderRadius: 18 }}>
181:           <div className="relative mb-1.5">
182:             <Icon name="search" size={14} className="absolute top-1/2 -translate-y-1/2 start-3 t-3" />
183:             <input autoFocus value={q} onChange={(e) => { setQ(e.target.value); setHi(0); }} onKeyDown={onKey} placeholder={searchPlaceholder}
184:               className="w-full h-9 rounded-xl ps-9 pe-8 text-[12.5px] outline-none" style={{ background: 'var(--bg-subcard)', color: 'var(--text-primary)' }} />
185:             {isLoading && <Spinner size={14} className="absolute top-1/2 -translate-y-1/2 end-3 t-acc" />}
186:           </div>
187:           <div className="max-h-[248px] overflow-y-auto">
188:             {isLoading ? (
189:               <div className="p-2 space-y-3">{[0, 1, 2].map((i) => <div key={i} className="flex items-center gap-2.5"><Skel w={22} h={22} r={8} /><Skel w={`${70 - i * 15}%`} h={10} /></div>)}</div>
190:             ) : list.length === 0 ? (
191:               <div className="py-6 px-3 text-center">
192:                 <div className="w-10 h-10 rounded-full v-well mx-auto flex items-center justify-center mb-2"><Icon name="search" size={16} /></div>
193:                 <div className="text-[12.5px] font-semibold t-1">{emptyText || 'لا توجد نتائج'}</div>
194:                 {q && <div className="text-[11.5px] t-3 mt-0.5">لا شيء يطابق «{q}»</div>}
195:               </div>
196:             ) : list.map((o, i) => {
197:               const sel = multi ? (value || []).includes(o.value) : o.value === value;
198:               return (
199:                 <button type="button" key={o.value} onMouseEnter={() => setHi(i)} onClick={() => !o.disabled && pick(o)} disabled={o.disabled}
200:                   className={cx('w-full flex items-center gap-2.5 px-2.5 py-2 rounded-xl text-start text-[12.5px] transition', hi === i && 'bg-[var(--bg-subcard)]', o.disabled && 'opacity-40 cursor-not-allowed')}
201:                   style={{ paddingInlineStart: o.depth ? 10 + o.depth * 16 : undefined }}>
202:                   {multi && <Check on={sel} />}
203:                   {o.icon}
204:                   <span className="flex-1 min-w-0">
205:                     <span className={cx('block truncate', sel ? 'font-semibold t-1' : 't-1')}>{o.label}</span>
206:                     {o.sub && <span className="block text-[11px] t-3 truncate">{o.sub}</span>}
207:                   </span>
208:                   {o.note && <span className="text-[10.5px] t-3">{o.note}</span>}
209:                   {!multi && sel && <Icon name="check" size={14} className="t-acc" sw={2.4} />}
210:                 </button>
211:               );
212:             })}
213:           </div>
214:         </div>
215:       )}
216:     </div>
217:   );
218: }
