227:   if (!open) return null;
228:   return (
229:     <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 fade" style={{ background: 'var(--overlay)', backdropFilter: 'blur(3px)' }} onMouseDown={(e) => e.target === e.currentTarget && onClose && onClose()}>
230:       <div role="dialog" aria-modal="true" aria-labelledby={titleId} className="pop v-card w-full overflow-hidden" style={{ maxWidth: width, boxShadow: 'var(--shadow-pop)', borderRadius: 26 }}>
231:         {(title || icon) && (
232:           <div className="p-6 pb-0 flex items-start gap-3.5">
233:             {icon && <span className={cx('w-11 h-11 rounded-full flex items-center justify-center shrink-0', 'b-' + iconTone)}><Icon name={icon} size={19} /></span>}
234:             <div className="flex-1 min-w-0 pt-0.5">
235:               <h3 id={titleId} className="font-display text-[17px] font-semibold t-1">{title}</h3>
