237:             </div>
238:             {onClose && <button className="icon-btn -mt-1 -me-1" onClick={onClose}><Icon name="x" size={16} /></button>}
239:           </div>
240:         )}
241:         <div className="p-6">{children}</div>
242:         {footer && <div className="px-6 pb-6 -mt-2 flex items-center justify-end gap-2">{footer}</div>}
243:       </div>
244:     </div>
245:   );
246: }
