693: const FORM_KEYS = ['ar', 'en', 'slug', 'desc_ar', 'desc_en', 'order', 'parentId', 'status', 'img'];
694: 
695: function CategoryForm({ open, value, tree, onClose, onSaved }) {
696:   const isEdit = value && value.id;
697:   const [v, setV] = useState({});
698:   const [slugTouched, setSlugTouched] = useState(false);
699:   const [errs, setErrs] = useState({});
700:   const [lang, setLang] = useState('ar');
701:   const [busy, setBusy] = useState(false);
702:   const [uploadProgress, setUploadProgress] = useState(null);
703:   const [fileChecking, setFileChecking] = useState(false);
704:   const previewUrlRef = useRef(null);
705:   useEffect(() => {
706:     if (!open) {
707:       if (previewUrlRef.current) { URL.revokeObjectURL(previewUrlRef.current); previewUrlRef.current = null; }
708:       return;
709:     }
710:     setBusy(false);
711:     setFileChecking(false);
712:     setUploadProgress(null);
713:     setErrs({});
714:     setLang('ar');
715:     if (previewUrlRef.current) { URL.revokeObjectURL(previewUrlRef.current); previewUrlRef.current = null; }
716:     if (isEdit) {
717:       const found = findNode(tree, value.id);
718:       setV({
719:         id: value.id,
720:         ar: value.ar || '',
721:         en: value.en || '',
722:         slug: value.slug || '',
723:         desc_ar: value.desc_ar || '',
724:         desc_en: value.desc_en || '',
725:         order: value.order ?? 0,
726:         status: value.status || 'active',
727:         parentId: value.parentId ?? found?.parent?.id ?? null,
728:         imageUrl: value.imageUrl,
729:         img: value.img,
730:         imageFile: null,
731:         imageRemoved: false,
732:         previewUrl: null,
733:       });
734:       setSlugTouched(true);
735:     } else {
736:       const parentId = value.parentId ?? value.parent ?? null;
737:       const siblings = parentId == null ? tree : (findNode(tree, parentId)?.node.children || []);
738:       setV({
739:         status: 'active',
740:         parentId,
741:         order: Math.max(-1, ...siblings.map((n) => Number(n.order) || 0)) + 1,
742:         ar: '', en: '', slug: '', desc_ar: '', desc_en: '',
743:         imageFile: null, imageRemoved: false, previewUrl: null, img: undefined, imageUrl: null,
744:       });
745:       setSlugTouched(false);
746:     }
747:   }, [open]);
748:   useEffect(() => () => { if (previewUrlRef.current) URL.revokeObjectURL(previewUrlRef.current); }, []);
749:   const generatedSlug = autoSlug(v.en);
750:   const flat = flattenCats(tree);
751:   const height = isEdit ? treeDepth(value) : 1;
752:   const parentName = v.parentId != null ? flat.find((f) => f.id === v.parentId)?.ar : null;
753:   const preview = v.previewUrl
754:     ? `url("${v.previewUrl}") center / cover no-repeat`
755:     : (v.imageRemoved ? null : (v.imageUrl ? `url("${v.imageUrl}") center / cover no-repeat` : v.img));
756:   const save = async () => {
757:     const e = {};
758:     if (!(v.ar || '').trim()) e.ar = 'الاسم العربي مطلوب';
759:     if (!(v.en || '').trim()) e.en = 'الاسم الإنجليزي مطلوب';
760:     if ((v.ar || '').length > 150) e.ar = 'الحد الأقصى 150 حرف';
761:     if ((v.en || '').length > 150) e.en = 'الحد الأقصى 150 حرف';
762:     const order = toLatinDigits(v.order ?? 0).trim();
763:     if (!/^\d+$/.test(order) || Number(order) > 2147483647) e.order = 'الترتيب يجب أن يكون عددًا صحيحًا من 0 إلى 2147483647';
764:     const slugVal = slugTouched ? v.slug : generatedSlug;
765:     if (v.slug && !/^[a-z0-9_-]+$/i.test(v.slug)) e.slug = 'حروف إنجليزي وأرقام و - فقط';
766:     setErrs(e);
767:     if (Object.keys(e).length) return;
768: 
769:     setBusy(true);
770:     setUploadProgress(v.imageFile ? 0 : null);
771:     try {
772:       const payload = toPayload({ ...v, slug: slugVal }, { isEdit });
773:       const onProgress = v.imageFile ? (pct) => setUploadProgress(pct) : undefined;
774:       if (isEdit) await categoriesApi.update(v.id, payload, onProgress);
775:       else await categoriesApi.create(payload, onProgress);
776:       vtoast(isEdit ? 'تم تحديث القسم' : 'تم إنشاء القسم');
777:       onSaved && onSaved();
778:       onClose();
779:     } catch (err) {
780:       const p = parseApiError(err);
781:       if (p.isValidation) {
782:         const formErrs = Object.fromEntries(Object.entries(p.fieldErrors).filter(([k]) => FORM_KEYS.includes(k)));
783:         if (Object.keys(formErrs).length) setErrs(formErrs);
784:         else vtoast(p.message);
785:       } else vtoast(p.message);
786:     } finally {
787:       setBusy(false);
788:       setUploadProgress(null);
789:     }
790:   };
791:   const close = () => { if (!busy) onClose(); };
792:   return (
793:     <Drawer open={open} onClose={close} title={isEdit ? 'تعديل القسم' : (v.parentId ? 'قسم فرعي جديد' : 'قسم رئيسي جديد')} subtitle={v.parentId && !isEdit && parentName ? <>تحت <b className="t-1"><bdi>{parentName}</bdi></b></> : null} width={540}
794:       footer={<><button className="btn btn-soft" onClick={close} disabled={busy}>إلغاء</button><button className="btn btn-ink" onClick={save} disabled={busy || fileChecking}>{(busy || fileChecking) && <Spinner size={14} />}{isEdit ? 'حفظ' : 'إنشاء القسم'}</button></>}>
795:       <fieldset disabled={busy} className="space-y-4">
796:         <div className="grid grid-cols-2 gap-3">
797:           <Field label="الاسم بالعربي" required error={errs.ar}><Input dir="rtl" value={v.ar || ''} onChange={(e) => setV({ ...v, ar: e.target.value })} error={errs.ar} /></Field>
798:           <Field label="الاسم بالإنجليزي" required error={errs.en}><Input ltr dir="ltr" value={v.en || ''} onChange={(e) => setV({ ...v, en: e.target.value })} error={errs.en} /></Field>
799:         </div>
800:         <Field label="القسم الأب" hint="اختياري — اتركه فارغًا لقسم رئيسي" error={errs.parentId}>
801:           <SearchSelect value={v.parentId || null} onChange={(p) => setV({ ...v, parentId: p })} placeholder="بدون أب (قسم رئيسي)"
802:             options={flat.map((f) => {
803:               const exceeds = (f.depth + 1) + height > MAX_DEPTH;
804:               const selfOrChild = isEdit && (f.id === value.id || isDescendant(value, f.id));
805:               return { value: f.id, label: f.ar, depth: f.depth, disabled: exceeds || selfOrChild, note: exceeds ? 'النقل هنا يتجاوز الحد الأقصى' : (selfOrChild ? (f.id === value.id ? 'نفسه' : 'فرعي منه') : null) };
806:             })} />
807:         </Field>
808:         <Field label="الرابط (slug)" error={errs.slug} hint={!slugTouched ? <>هيتولد تلقائيًا من الاسم الإنجليزي</> : null} aside={slugTouched && <button type="button" className="text-[11px] font-semibold t-acc" onClick={() => { setSlugTouched(false); setV({ ...v, slug: '' }); }}>استخدام التلقائي</button>}>
809:           <div className="relative"><span className="absolute top-1/2 -translate-y-1/2 left-3.5 text-[12.5px] t-3 ltr" dir="ltr">/categories/</span>
810:             <input className="v-input ltr" dir="ltr" style={{ paddingLeft: 98 }} value={slugTouched ? v.slug || '' : generatedSlug} placeholder="auto-generated" onChange={(e) => { setSlugTouched(true); setV({ ...v, slug: e.target.value }); }} />
811:           </div>
812:         </Field>
813:         <Field label="الوصف" error={lang === 'ar' ? errs.desc_ar : errs.desc_en} aside={<Seg value={lang} onChange={setLang} options={[{ value: 'ar', label: 'عربي' }, { value: 'en', label: 'EN' }]} />}>
814:           {lang === 'ar' ? <Textarea dir="rtl" value={v.desc_ar || ''} onChange={(e) => setV({ ...v, desc_ar: e.target.value })} /> : <Textarea className="ltr" dir="ltr" value={v.desc_en || ''} onChange={(e) => setV({ ...v, desc_en: e.target.value })} />}
815:         </Field>
816:         <Field label="صورة القسم" error={errs.img}>
817:           <ImageField value={preview} progress={uploadProgress} disabled={busy} onChecking={setFileChecking}
818:             onFile={(file, url) => {
819:               if (previewUrlRef.current) URL.revokeObjectURL(previewUrlRef.current);
820:               previewUrlRef.current = url;
821:               setV({ ...v, imageFile: file, imageRemoved: false, previewUrl: url });
822:             }}
823:             onRemove={() => {
824:               if (previewUrlRef.current) { URL.revokeObjectURL(previewUrlRef.current); previewUrlRef.current = null; }
825:               setV({ ...v, imageFile: null, imageRemoved: true, previewUrl: null, img: undefined });
826:             }} />
827:         </Field>
828:         <div className="grid grid-cols-[120px_1fr] gap-3">
829:           <Field label="الترتيب" error={errs.order}><Input ltr dir="ltr" type="text" inputMode="numeric" value={v.order ?? ''} onChange={(e) => setV({ ...v, order: e.target.value })} /></Field>
830:           <div className="v-subcard p-3.5 flex items-center justify-between self-end h-[42px] !rounded-[13px]"><span className="text-[12.5px] font-semibold t-1">نشط</span><Toggle on={v.status === 'active'} onChange={(on) => setV({ ...v, status: on ? 'active' : 'inactive' })} /></div>
831:         </div>
832:       </fieldset>
833:     </Drawer>
834:   );
835: }
836: 
837: function Drawer({ open, onClose, title, subtitle, children, footer, width = 520 }) {
838:   const titleId = useId();
839:   useEffect(() => {
840:     if (!open) return;
841:     const h = (e) => e.key === 'Escape' && onClose();
842:     window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);
843:   }, [open, onClose]);
844:   if (!open) return null;
845:   return (
846:     <div className="fixed inset-0 z-[60] fade" style={{ background: 'var(--overlay)', backdropFilter: 'blur(2px)' }} onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
847:       <div role="dialog" aria-modal="true" aria-labelledby={titleId} className="drawer absolute top-3 bottom-3 start-3 v-card flex flex-col overflow-hidden" style={{ width, maxWidth: 'calc(100vw - 24px)', boxShadow: 'var(--shadow-pop)', borderRadius: 26 }}>
848:         <div className="px-6 pt-6 pb-4 flex items-start justify-between gap-3 v-border-b">
849:           <div>
850:             <h3 id={titleId} className="font-display text-[19px] font-semibold t-1">{title}</h3>
851:             {subtitle && <p className="text-[12.5px] t-2 mt-0.5">{subtitle}</p>}
852:           </div>
853:           <button className="icon-btn" onClick={onClose}><Icon name="x" size={16} /></button>
854:         </div>
855:         <div className="flex-1 overflow-y-auto px-6 py-5">{children}</div>
856:         {footer && <div className="px-6 py-4 v-border-t flex items-center justify-end gap-2">{footer}</div>}
857:       </div>
858:     </div>
859:   );
860: }
