944: function useCategoriesTree(enabled) {
945:   const [phase, setPhase] = useState('loading'); // loading | error | empty | ready
946:   const [tree, setTree] = useState([]);
947:   const [saved, setSaved] = useState([]);
948:   const [error, setError] = useState(null);
949:   const request = useRef(null);
950:   const generation = useRef(0);
951: 
952:   const load = useCallback(async ({ silent = false } = {}) => {
953:     if (!enabled) return;
954:     request.current?.abort();
955:     const controller = new AbortController();
956:     request.current = controller;
957:     const current = ++generation.current;
958:     if (!silent) setPhase('loading');
959:     try {
960:       const data = toUiTree(await categoriesApi.tree(controller.signal));
961:       if (controller.signal.aborted || current !== generation.current) return;
962:       setTree(data); setSaved(data); setError(null);
963:       setPhase(data.length ? 'ready' : 'empty');
964:     } catch (e) {
965:       if (controller.signal.aborted || current !== generation.current) return;
966:       const err = parseApiError(e);
967:       setError(err);
968:       if (!silent) setPhase('error'); else vtoast(err.message);
969:     }
970:   }, [enabled]);
971: 
972:   useEffect(() => {
973:     load();
974:     return () => { generation.current++; request.current?.abort(); };
975:   }, [load]);
976:   return { phase, tree, setTree, saved, setSaved, error, reload: load };
977: }
