18: class Category extends Model implements HasMedia
19: {
20:     /** @use HasFactory<CategoryFactory> */
21:     use HasFactory, InteractsWithMedia, SoftDeletes;
22: 
23:     protected $fillable = ['parent_id', 'name_ar', 'name_en', 'slug', 'description_ar', 'description_en', 'sort_order', 'is_active'];
24: 
25:     protected $casts = ['is_active' => 'boolean'];
26: 
27:     public function parent(): BelongsTo
28:     {
29:         return $this->belongsTo(Category::class, 'parent_id');
30:     }
31: 
32:     public function children(): HasMany
33:     {
34:         return $this->hasMany(Category::class, 'parent_id')->orderBy('sort_order');
35:     }
36: 
37:     public function products(): HasMany
38:     {
39:         return $this->hasMany(Product::class);
40:     }
41: 
42:     /** المنتجات المنشورة فقط — أساس عدّادات أقسام المتجر. */
43:     public function activeProducts(): HasMany
44:     {
45:         return $this->hasMany(Product::class)->where('status', ProductStatus::Published)
46:             ->whereIn('sales_channel', [SalesChannel::Retail, SalesChannel::Both])
47:             ->where(fn ($q) => $q->whereNull('brand_id')->orWhereHas('brand', fn ($brand) => $brand->where('is_active', true)));
48:     }
49: 
50:     public function registerMediaCollections(): void
51:     {
52:         $this->addMediaCollection('image')->singleFile()
53:             ->acceptsMimeTypes(['image/jpeg', 'image/png', 'image/webp']);
54:     }
55: 
56:     // بيرجّع IDs كل الأقسام اللي تحته على أي مستوى — مجموعة visited بتمنع اللف اللانهائي لو فيه دورة في البيانات
57:     public function descendantIds(): array
58:     {
59:         $ids = [];
60:         $seen = [$this->id => true];
61:         $queue = [$this->id];
62:         while ($queue) {
63:             $children = Category::whereIn('parent_id', $queue)->pluck('id')->all();
64:             $queue = [];
65:             foreach ($children as $childId) {
66:                 if (! isset($seen[$childId])) {
67:                     $seen[$childId] = true;
68:                     $ids[] = $childId;
69:                     $queue[] = $childId;
70:                 }
71:             }
72:         }
73: 
74:         return $ids;
75:     }
76: 
77:     public function depth(): int
78:     {
79:         $depth = 1;
80:         $seen = [$this->id => true];
81:         $p = $this->parent;
82:         while ($p) {
83:             if (isset($seen[$p->id])) {
84:                 throw new \RuntimeException('توجد دورة في شجرة الأقسام');
85:             }
86:             $seen[$p->id] = true;
87:             $depth++;
88:             $p = $p->parent;
89:         }
90: 
91:         return $depth;
92:     }
