101: const MULTIPART = { headers: { 'Content-Type': 'multipart/form-data' } };
102: 
103: function categoryFormData(p: CategoryPayload, spoofPut = false): FormData {
104:   const fd = new FormData();
105:   if (spoofPut) fd.append('_method', 'PUT');
106:   const put = (key: string, v: unknown) => {
107:     if (v === undefined) return;                       // مش هيتبعت
108:     if (v === null) return fd.append(key, '');         // Laravel يحوّلها null
109:     if (typeof v === 'boolean') return fd.append(key, v ? '1' : '0'); // مهم: مش "true"
110:     if (v instanceof Blob) return fd.append(key, v);
111:     fd.append(key, String(v));
112:   };
113:   put('parent_id', p.parent_id);
114:   put('name_ar', p.name_ar);
115:   put('name_en', p.name_en);
116:   put('slug', p.slug);
117:   put('description_ar', p.description_ar);
118:   put('description_en', p.description_en);
119:   put('sort_order', p.sort_order);
120:   put('is_active', p.is_active);
121:   if (p.image) put('image', p.image);
122:   if (p.remove_image) put('remove_image', true);
123:   return fd;
124: }
