 5: export interface ApiClientConfig {
 6:   baseURL?: string;
 7:   withCredentials?: boolean;
 8:   getToken?: () => string | null | undefined;
 9:   onUnauthorized?: () => void;
10: }
11: 
12: let activeToken: string | null = null;
13: let unauthorizedHandler: (() => void) | null = null;
14: 
15: export function setAuthToken(token: string | null) {
16:   activeToken = token;
17: }
18: 
19: export function getAuthToken(): string | null {
20:   return activeToken;
21: }
22: 
23: export function setUnauthorizedHandler(handler: (() => void) | null) {
24:   unauthorizedHandler = handler;
25: }
26: 
27: export function createApiClient(config: ApiClientConfig = {}): AxiosInstance {
28:   const envBaseUrl = typeof process !== 'undefined' && process.env 
29:     ? (process.env.NEXT_PUBLIC_API_URL || process.env.VITE_API_URL) 
30:     : undefined;
31: 
32:   const instance = axios.create({
33:     baseURL: config.baseURL || envBaseUrl || 'http://localhost:8000',
34:     timeout: 30000,
35:     withCredentials: config.withCredentials ?? false,
36:     headers: {
37:       'Content-Type': 'application/json',
38:       Accept: 'application/json',
39:       'X-Requested-With': 'XMLHttpRequest',
40:     },
41:   });
42: 
43:   instance.interceptors.request.use((reqConfig: InternalAxiosRequestConfig) => {
44:     const existingAuth = reqConfig.headers?.Authorization ?? (reqConfig.headers as Record<string, unknown>)?.['authorization'];
45:     if (existingAuth) {
46:       return reqConfig;
47:     }
48:     const token = config.getToken ? config.getToken() : activeToken;
49:     if (token && reqConfig.headers) {
50:       reqConfig.headers.Authorization = `Bearer ${token}`;
51:     }
52:     return reqConfig;
53:   });
54: 
55:   instance.interceptors.response.use(
56:     (response) => response,
57:     (error) => {
58:       const isSignInRequest = ['/api/v1/auth/login', '/api/v1/auth/handoff/exchange']
59:         .some((path) => error.config?.url?.split('?')[0] === path);
60:       const currentToken = config.getToken ? config.getToken() : activeToken;
61:       const requestAuth = error.config?.headers?.Authorization ?? error.config?.headers?.authorization;
62:       const staleSession = typeof requestAuth === 'string' && requestAuth.startsWith('Bearer ')
63:         && requestAuth !== `Bearer ${currentToken}`;
64:       if (error.response?.status === 401 && !isSignInRequest && !staleSession) {
65:         if (config.onUnauthorized) {
66:           config.onUnauthorized();
67:         } else if (unauthorizedHandler) {
68:           unauthorizedHandler();
69:         }
70:       }
71:       return Promise.reject(error);
72:     }
73:   );
74: 
75:   return instance;
76: }
